function convertRawToWord(item: typeof JOHN_CHAPTER_1_WORDS_RAW[0], index: number): GreekWord {
  const phonetics = convertGreekToErasmianPhonetics(item.lemma);
  const chapterNum = item.verseRef.split(' ')[1].split(':')[0];
  const greekForm = item.lemma;
  const mnemonic = getMnemonicForWord({ greek: greekForm, lemma: item.lemma, translationRu: item.translation });

  const textFormStr = (item as any).textForm ? (item as any).textForm : item.lemma;
  const contextGreekStr = (item as any).contextPhrase || textFormStr;
  const contextRuStr = (item as any).contextRu || item.translation;

  return {
    id: `john${chapterNum}_w_${index + 1}`,
    greek: greekForm,
    lemma: item.lemma,
    transliterationRu: phonetics,
    erasmianIpa: phonetics,
    partOfSpeech: 'noun',
    translationRu: item.translation,
    additionalMeaningsRu: (item as any).additionalMeanings || [item.translation],
    ntFrequency: item.frequency,
    frequencyCategory: item.frequency >= 50 ? '50-100' : item.frequency >= 20 ? '20-50' : item.frequency >= 10 ? '10-20' : '<10',
    thematicGroup: 'theology_church',
    thematicGroupNameRu: 'Евангелие от Иоанна',
    chapters: [`john_${chapterNum}`],
    exampleVerse: {
      reference: item.verseRef,
      greekText: contextGreekStr,
      translationRu: contextRuStr,
      highlightWord: textFormStr,
    },
    erasmianNotes: 'Эразмово произношение: точное ударение и аутентичная артикуляция дифтонгов и согласных.',
    mnemonicRu: mnemonic,
  };
}

